#!/bin/bash
set -euo pipefail

# Generated by Copilot

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
WASM_DIR="${ROOT_DIR}/wasm"
BUILD_DIR="${WASM_DIR}/build"
DIST_DIR="${WASM_DIR}/dist"

LIBCLANG_PATH="${LIBCLANG_PATH:-/opt/homebrew/opt/llvm/lib/libclang.dylib}"

if ! command -v emcc >/dev/null 2>&1; then
  echo "Emscripten not found. Run: source ~/.emsdk/emsdk_env.sh"
  exit 1
fi

if ! command -v python >/dev/null 2>&1; then
  echo "python not found in PATH"
  exit 1
fi

if [[ "${1:-}" == "--clean" || "${CLEAN:-0}" == "1" ]]; then
  rm -rf "${BUILD_DIR}" "${DIST_DIR}"
fi

mkdir -p "${BUILD_DIR}" "${DIST_DIR}"

if [ -f "${WASM_DIR}/generate_bindings.py" ]; then
  LIBCLANG_PATH="${LIBCLANG_PATH}" python "${WASM_DIR}/generate_bindings.py" --use-clang
fi

emcmake cmake -S "${WASM_DIR}" -B "${BUILD_DIR}" -DCMAKE_BUILD_TYPE=Release
emmake make -C "${BUILD_DIR}" -j4

echo "Build complete:"
echo "- ${DIST_DIR}/aaplus.js"
echo "- ${DIST_DIR}/aaplus.wasm"
echo "- ${DIST_DIR}/aaplus.d.ts"

# rm -rf "${BUILD_DIR}" 

